 s+=VB(60,120,X(0.35)-60,56,{fill:'#DBE4FF',st:BLU,r:6})+VT(76,156,'short path 0.35 ns',{fs:22,fw:700})+VB(X(0.35),120,50,56,{fill:'#D3F9D8',st:GRN,r:6})+VL(X(0.38),96,X(0.38),214,GRN,4,'stroke-dasharray="8 6"')+VT(X(0.38)+28,112,'needs 0.38 ns',{fs:22,fw:800,fill:GRN})+VT(X(0.35)+25,206,'+0.05',{fs:22,fw:800,a:'middle',fill:GRN});
